def min_cost(m, n):
    # Cells reachable at all: (0,0), (0,1), (1,0) because i + j alternates 1, 0, 1, 0, ...
    if m == 1 and n == 1:
        return 1            # already at the destination, pay only (0+1)*(0+1)
    if (m == 2 and n == 1) or (m == 1 and n == 2):
        return 3            # 1 for entering (0,0) plus 2 for entering (1,0) or (0,1)
    return -1
